INSERT INTO tasks (title, details, owner, status, due, created_by, updated_by, evidence, created_at, updated_at) VALUES ('Approve the Burns & McDonnell transcript email', 'Drafted email to recruiting@burnsmcd.com attaching her unofficial MSc transcript, subject "Unofficial Transcript — Jesutofunmi Adewole — 2027 Summer Internship". Nayden sends it the moment she approves.', 'Jesutofunmi', 'waiting', '2026-11-12', 'Nayden', 'Nayden', '', '2026-11-10T05:00:00.000Z', '2026-11-10T05:00:00.000Z');
